// 1. Obtener los datos de los nodos anteriores
const licitaciones = $('CargaLicitaciones').all().map(item => item.json);
const usuarios = $('CargaUsuarios').all().map(item => item.json);

// 2. Obtener el histórico de envíos desde el nodo 'Leer Envios_log'
let enviosLog = [];
try {
  enviosLog = $('Leer Envios_log').all().map(item => item.json);
} catch (e) {
  enviosLog = [];
}

const resultado = [];

for (const usuario of usuarios) {
  const sectoresUsuario = Array.isArray(usuario.sectores) ? usuario.sectores : [];
  const estadosUsuario = Array.isArray(usuario.estados) ? usuario.estados : [];

  // Obtener los proceso_id de las licitaciones que ESTE usuario ya recibió anteriormente
  const licitacionesYaEnviadas = enviosLog
    .filter(log => log.usuario_id === usuario.id)
    .map(log => log.proceso_id); // =H Cambiado a proceso_id para que coincida con tu nueva estructura

  // Filtrar licitaciones del día que:
  // - Coincidan con el sector del usuario
  // - Coincidan con el estado geográfico (si tiene estados configurados)
  // - NO hayan sido enviadas previamente (evita duplicados)
  const licitacionesValidas = licitaciones.filter(lic => {
    const coincideSector = sectoresUsuario.includes(lic.sector);
    const coincideEstado = estadosUsuario.length === 0 || estadosUsuario.includes(lic.estado);
    const idProcesoActual = lic.proceso_id || lic.numero_proceso;
    const yaFueEnviada = licitacionesYaEnviadas.includes(idProcesoActual);

    return coincideSector && coincideEstado && !yaFueEnviada;
  });

  // Solo incluimos al usuario si tiene licitaciones nuevas para enviarle hoy
  if (licitacionesValidas.length > 0) {
    resultado.push({
      json: {
        ...usuario,
        licitaciones: licitacionesValidas,
        enviar_boletin: true
      }
    });
  }
}

return resultado;

for (const item of $input.all()) {
  const usuario = item.json;
  const licitaciones = usuario.licitaciones || [];

  let contenidoHtml = '';

  if (licitaciones.length === 0) {
    contenidoHtml = `
      <div style="padding: 20px; text-align: center; background-color: #f8fafc; border-radius: 6px; color: #64748b; font-size: 13px;">
        No se encontraron nuevas licitaciones en tus sectores el día de hoy.
      </div>
    `;
  } else {
    // 1. Agrupar por Estado geográfico
    const agrupadasPorEstado = {};
    for (const lic of licitaciones) {
      const estado = lic.estado || 'Nacional / Sin Especificar';
      if (!agrupadasPorEstado[estado]) agrupadasPorEstado[estado] = [];
      agrupadasPorEstado[estado].push(lic);
    }

    // 2. Generar el HTML agrupado
    contenidoHtml = Object.keys(agrupadasPorEstado).map(nombreEstado => {
      const listaLicitaciones = agrupadasPorEstado[nombreEstado];

      const tarjetas = listaLicitaciones.map(lic => {
        const esModificada = lic.es_modificado === true;
        const borderColor = esModificada ? '#ef4444' : '#e2e8f0';
        const bgColor = esModificada ? '#fef2f2' : '#fafafa';

        const tagModificada = esModificada 
          ? `<span style="font-size: 11px; font-weight: bold; color: #ffffff; background-color: #ef4444; padding: 3px 8px; border-radius: 4px; margin-left: 6px;">  PRÓRROGA / MODIFICADA</span>` 
          : '';

        return `
          <div style="border: 1px solid ${borderColor}; border-radius: 8px; padding: 16px; margin-bottom: 14px; background-color: ${bgColor}; text-align: left;">
            <div style="margin-bottom: 8px;">
              <span style="font-size: 12px; font-weight: bold; color: #2563eb; background-color: #dbeafe; padding: 4px 8px; border-radius: 4px; text-transform: uppercase;">
                ${lic.sector || 'General'}
              </span>
              ${tagModificada}
            </div>

            <h4 style="margin: 6px 0; font-size: 14px; color: #1e293b; font-weight: 600;">
              <Û ${lic.ente_nombre || lic.organismo || 'Organismo Público'}
            </h4>

            <p style="margin: 8px 0 12px 0; font-size: 13px; color: #334155; line-height: 1.4;">
              ${lic.descripcion_objeto || 'Sin descripción detallada'}
            </p>


            <div style="border-top: 1px solid #f1f5f9; padding-top: 10px; margin-top: 10px; display: flex; align-items: center; justify-content: space-between;">

              <!-- *********************
              <span style="font-size: 12px; color: #64748b;">
                =Å Límite: <strong>${lic.fecha_recepcion_ofertas || lic.fecha_limite || 'Por definir'}</strong>
              </span> 
              *********************** -->

              <a href="${lic.url_pliego || lic.url_publica || '#'}" style="background-color: ${esModificada ? '#991b1b' : '#0f172a'}; color: #ffffff; padding: 6px 14px; text-decoration: none; border-radius: 5px; font-size: 12px; font-weight: bold; display: inline-block;">
                ${esModificada ? 'Ver Adenda / Cambio ’' : 'Ver detalle ’'}
              </a>
            </div>
          </div>
        `;
      }).join('');

      return `
        <div style="margin-top: 24px; margin-bottom: 12px; border-bottom: 2px solid #2563eb; padding-bottom: 6px; text-align: left;">
          <h3 style="margin: 0; font-size: 15px; color: #1e293b; text-transform: uppercase; font-weight: 700;">
            =Í Estado: ${nombreEstado}
          </h3>
        </div>
        ${tarjetas}
      `;
    }).join('');
  }

  // 3. Crear el HTML completo del boletín
  item.json.boletin_html = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
    </head>
    <body style="font-family: 'Segoe UI', Arial, sans-serif; background-color: #f4f6f8; margin: 0; padding: 20px; color: #333333;">
