        <div style="background-color: #0f172a; padding: 24px; text-align: left; color: #ffffff;">
          <h2 style="margin: 0; font-size: 20px; font-weight: 600;"><û<ê Licitaciones Venezuela</h2>
          <p style="margin: 6px 0 0 0; font-size: 13px; color: #94a3b8;">Resumen diario de oportunidades de contratación pública</p>
        </div>

        <div style="padding: 24px 24px 12px 24px; text-align: left;">
          <p style="margin: 0 0 10px 0; font-size: 15px;">Hola <strong>${usuario.nombre || 'Suscriptor'}</strong>,</p>
          <p style="margin: 0; font-size: 14px; color: #475569; line-height: 1.5;">
            Hemos detectado <strong>${licitaciones.length} licitaciones</strong> publicadas hoy en tus sectores y regiones seleccionados:
          </p>
        </div>

        <div style="padding: 12px 24px 24px 24px;">
          ${contenidoHtml}
        </div>

        <div style="background-color: #f8fafc; padding: 20px; text-align: center; border-top: 1px solid #e2e8f0; font-size: 12px; color: #64748b;">
          <p style="margin: 0 0 8px 0;">¿Deseas ajustar las alertas que recibes?</p>
          <p style="margin: 0;">
            <a href="https://somewhat-jones-marion-guru.trycloudflare.com/webhook/preferencias?token=${usuario.access_token}&action=update" style="color: #2563eb; text-decoration: underline;">Gestionar mis sectores</a>
            &nbsp;|&nbsp;
            <a href="https://somewhat-jones-marion-guru.trycloudflare.com/webhook/desuscripcion?token=${usuario.access_token}&action=cancel" style="color: #ef4444; text-decoration: underline;">Darse de baja</a>
          </p>
          <p style="margin-top: 12px; font-size: 11px; color: #94a3b8;">Licitaciones Venezuela © 2026</p>
        </div>

      </div>
    </body>
    </html>
  `;
}

